WITH e AS (SELECT * EXCEPT (npc_name), ifNull(npc_name, '') AS npc_name FROM npc_shops WHERE capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')) SELECT e.zone_id AS zone, any(z.name) AS zone_name, e.npc_name AS npc_name, e.kind AS kind, e.item_id AS item, any(i.name) AS item_name, min(e.price) AS price_lo, max(e.price) AS price_hi, sum(e.n) AS n, uniqExact(e.capture_id) AS captures FROM e LEFT JOIN (SELECT id, any(name) AS name FROM item_names WHERE id IN (SELECT item_id FROM e) GROUP BY id) i ON i.id = e.item_id LEFT JOIN (SELECT id, any(name) AS name FROM zone_names GROUP BY id) z ON z.id = e.zone_id GROUP BY e.zone_id, e.npc_name, e.kind, e.item_id ORDER BY item_name, zone_name, npc_name, kind
